1	//! `Vec<Item>` + `ModelRequest` → Anthropic Messages request body.
2	//!
3	//! Rules per the SMA-317 spec § "Wire translation". The translator
4	//! produces a `serde_json::Value` rather than typed structs to keep the
5	//! wire-snapshot tests readable.
6	//!
7	//! SMA-840: an assistant message can hold `ProviderData` parts of this crate.
8	//! They carry the `thinking` and `redacted_thinking` blocks of the response,
9	//! and the positions of its first `text` block and its `tool_use` blocks. The
10	//! translator sends the blocks back and puts the blocks of each source
11	//! message in their response order. A history with no such part builds as
12	//! before.
13	
14	use std::collections::{HashMap, VecDeque};
15	
16	use paigasus_helikon_core::{ContentPart, Item};
17	use serde_json::{json, Value};
18	
19	use crate::provider_data::{self, AnthropicData};
20	
21	/// Output of [`translate_messages`]: the top-level `system` field (string
22	/// or block-array form) and the `messages` array.
23	pub(crate) struct TranslatedMessages {
24	    pub(crate) system: Option<Value>,
25	    pub(crate) messages: Value,
26	    /// `true` when the last user message produced no message, no kept
27	    /// message or tool item follows it (dropped assistant items do not
28	    /// count), and the last sent message is an assistant one.
29	    pub(crate) trailing_message_dropped: bool,
30	}
31	
32	/// The sort key of a block inside its group.
33	#[derive(Debug, Clone, Copy)]
34	enum SortKey {
35	    /// `(index, 1)`, where `index` is the content-block index of the
36	    /// response. A `tool_use` block with no position has `(u64::MAX, 1)`.
37	    At(u64, u8),
38	    /// A text block of a group with no `text` position. The key becomes
39	    /// `(k, 0)`, where `k` is the smallest keyed `tool_use` index of the group
40	    /// in the same wire message, or `u64::MAX` when there is none.
41	    BeforeFirstToolUse,
42	}
43	
44	impl SortKey {
45	    fn resolve(self, first_tool_use: u64) -> (u64, u8) {
46	        match self {
47	            Self::At(index, rank) => (index, rank),
48	            Self::BeforeFirstToolUse => (first_tool_use, 0),
49	        }
50	    }
51	}
