53	/// The place of a block in the response order of its source message.
54	#[derive(Debug, Clone, Copy)]
55	struct Slot {
56	    /// The source message of the block. Keys of different groups are never
57	    /// compared.
58	    group: usize,
59	    key: SortKey,
60	}
61	
62	/// One content block of a wire message. Only `value` reaches the JSON.
63	#[derive(Debug, Clone, Default)]
64	struct WireBlock {
65	    value: Value,
66	    /// `None` for a block that does not move in the final sort.
67	    slot: Option<Slot>,
68	}
69	
70	impl WireBlock {
71	    fn plain(value: Value) -> Self {
72	        Self { value, slot: None }
73	    }
74	
75	    fn kind(&self) -> &str {
76	        self.value["type"].as_str().unwrap_or("")
77	    }
78	
79	    fn is_tool_use(&self) -> bool {
80	        self.kind() == "tool_use"
81	    }
82	
83	    fn is_thinking(&self) -> bool {
84	        matches!(self.kind(), "thinking" | "redacted_thinking")
85	    }
86	}
