88	/// One message of the `messages` array, before it becomes JSON.
89	#[derive(Debug, Clone)]
90	struct WireMessage {
91	    role: &'static str,
92	    content: Vec<WireBlock>,
93	}
94	
95	impl WireMessage {
96	    /// `true` when the message holds a `text` or `tool_use` block of group
97	    /// `group`.
98	    fn has_own_block(&self, group: usize) -> bool {
99	        self.content
100	            .iter()
101	            .any(|b| !b.is_thinking() && b.slot.is_some_and(|s| s.group == group))
102	    }
103	
104	    fn into_value(mut self) -> Value {
105	        drop_thinking_without_own_block(&mut self.content);
106	        sort_groups(&mut self.content);
107	        let content: Vec<Value> = self.content.into_iter().map(|b| b.value).collect();
108	        json!({"role": self.role, "content": content})
109	    }
110	}
