112	/// The Anthropic positions of one source message: an `AssistantMessage`
113	/// with at least one valid part of this crate, together with the
114	/// `Item::ToolCall` items that follow it before the next `AssistantMessage`
115	/// or the next user message with a part that is not a tool result.
116	#[derive(Debug, Clone)]
117	struct Source {
118	    group: usize,
119	    /// The wire message that holds the blocks of the `AssistantMessage`.
120	    /// `None` when it gave no block.
121	    wire: Option<usize>,
122	    /// The `tool_use` positions by call id, in the order of the parts.
123	    tool_positions: HashMap<String, VecDeque<u64>>,
124	}
125	
126	impl Source {
127	    /// The key of the next `tool_use` block with `call_id`. Each position is
128	    /// used once, so a repeated id takes its positions in order.
129	    fn tool_key(&mut self, call_id: &str) -> SortKey {
130	        let index = self
131	            .tool_positions
132	            .get_mut(call_id)
133	            .and_then(VecDeque::pop_front);
134	        SortKey::At(index.unwrap_or(u64::MAX), 1)
135	    }
136	}
