138	/// The translator state before the item that made a tentative message.
139	#[derive(Debug)]
140	struct Saved {
141	    item: usize,
142	    messages_len: usize,
143	    system_len: usize,
144	    pending_tool_use: Vec<WireBlock>,
145	    pending_tool_results: Vec<Value>,
146	    last_item_dropped: bool,
147	    next_group: usize,
148	    source: Option<Source>,
149	}
