151	/// A wire assistant message that an item with only thinking blocks made.
152	///
153	/// It stays the last message until a message is pushed after it. If it then
154	/// (or at the end) has no `text` and no `tool_use` block of group `group`,
155	/// the translator goes back to `saved`, drops the thinking blocks of the
156	/// item, and translates again from that item. The item then counts as empty,
157	/// as it did before SMA-840: no flush, no message, and no change to the flag.
158	#[derive(Debug)]
159	struct Tentative {
160	    msg: usize,
161	    group: usize,
162	    saved: Saved,
163	}
164	
165	/// The signal to go back to the saved state of the tentative message.
166	struct Rollback;
167	
168	#[derive(Debug, Default)]
169	struct Translator {
170	    system_text: String,
171	    messages: Vec<WireMessage>,
172	    pending_tool_use: Vec<WireBlock>,
173	    pending_tool_results: Vec<Value>,
174	    last_item_dropped: bool,
175	    next_group: usize,
176	    source: Option<Source>,
177	    tentative: Option<Tentative>,
178	}
179	
180	/// Translate the conversation into Anthropic's request shape.
181	///
182	/// `system` is `None` when no `Item::System` has non-blank text. `messages`
183	/// is always an array. Text parts that are empty or whitespace only, and
184	/// messages left with no blocks, are dropped because the API rejects them.
185	///
186	/// A source message keeps its thinking blocks only when their wire message
187	/// also holds a `text` or `tool_use` block of the same source message. Else
188	/// the thinking blocks are dropped, and the item builds as if it had no
189	/// Anthropic part. A thinking block must not go into a round that a
190	/// different response made.
191	///
192	/// - The thinking blocks of an item that joins an open round are removed in
193	///   the final pass when the rule fails. These blocks change no other
194	///   decision, so the result is the same as with no such blocks.
195	/// - An item with only thinking blocks that makes a new message can change
196	///   the flushes. When the rule fails for it, the translator goes back and
197	///   translates again from that item, with its thinking blocks dropped.
198	///   Decisions go in item order.
199	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
200	    let mut t = Translator::default();
201	    let mut drop_thinking = vec![false; items.len()];
202	    let mut i = 0;
203	    loop {
204	        let done = i == items.len();
205	        let step = if done {
206	            t.finish()
207	        } else {
208	            t.step(i, &items[i], drop_thinking[i])
209	        };
210	        match step {
211	            Ok(()) if done => break,
212	            Ok(()) => i += 1,
213	            Err(Rollback) => {
214	                let tentative = t
215	                    .tentative
216	                    .take()
217	                    .expect("a rollback needs a tentative message");
218	                i = tentative.saved.item;
219	                // Each rollback drops one more item, so the loop ends.
220	                drop_thinking[i] = true;
221	                t.restore(tentative.saved);
222	            }
223	        }
224	    }
225	    t.into_output()
226	}
227	
228	impl Translator {
229	    fn step(&mut self, i: usize, item: &Item, drop_thinking: bool) -> Result<(), Rollback> {
230	        match item {
231	            Item::System { content } => {
232	                self.flush_pending_assistant()?;
233	                self.flush_pending_user()?;
234	                if !self.system_text.is_empty() {
235	                    self.system_text.push('\n');
236	                }
237	                self.system_text.push_str(&text_of(content));
238	            }
239	            Item::UserMessage { content } => {
240	                // A user message with a part that is not a tool result ends
241	                // the source message (the SMA-827 Gemini rule).
242	                if content
243	                    .iter()
244	                    .any(|p| !matches!(p, ContentPart::ToolResult { .. }))
245	                {
246	                    self.source = None;
247	                }
248	                self.flush_pending_assistant()?;
249	                // Pending tool_results go at the front of this user turn.
250	                let mut blocks: Vec<Value> = std::mem::take(&mut self.pending_tool_results);
251	                blocks.extend(user_blocks(content));
252	                self.last_item_dropped = blocks.is_empty();
253	                if !blocks.is_empty() {
254	                    let blocks = blocks.into_iter().map(WireBlock::plain).collect();
255	                    self.push_message("user", blocks)?;
256	                }
257	            }
258	            Item::AssistantMessage { content, agent: _ } => {
259	                let (mut blocks, source) = assistant_blocks(content, self.next_group);
260	                if drop_thinking {
261	                    blocks.retain(|b| !b.is_thinking());
262	                }
263	                // An assistant item with no blocks acts as if it were absent:
264	                // it flushes nothing (so an open tool round stays whole) and
265	                // leaves the flag as it is (a drop of the user turn before
266	                // it still counts). A kept assistant message ends the drop.
267	                //
268	                // A message of only tool uses and thinking blocks is the
269	                // nested form of `Item::ToolCall`, or the accumulator form of
270	                // a thinking round (SMA-834, SMA-840). Inside an open round it
271	                // joins that round, as a call does. A flush would put a user
272	                // turn that lacks some results right after the open assistant
273	                // turn. On this path the last message is an assistant message
274	                // (`round_is_answered` is `true` for an empty trailing
275	                // assistant run). `pending_tool_use` is empty, because each
276	                // `ToolResult` flushes it. So the append keeps the order.
277	                // Setting `last_item_dropped` here is for symmetry. The flag
278	                // is already `false`, because a `ToolResult` came after any
279	                // dropped user message.
280	                let only_tool_uses =
281	                    !blocks.is_empty() && blocks.iter().all(|b| b.is_tool_use() || b.is_thinking());
282	                let joins = only_tool_uses
283	                    && !self.pending_tool_results.is_empty()
284	                    && !round_is_answered(&self.messages, &self.pending_tool_results);
285	                let thinking_only = !blocks.is_empty() && blocks.iter().all(WireBlock::is_thinking);
286	                let saved = (thinking_only && !joins).then(|| self.save(i));
287	                if source.is_some() {
288	                    self.next_group += 1;
289	                }
290	                self.source = source;
291	                if joins {
292	                    self.last_item_dropped = false;
293	                    let target = self.tool_use_target();
294	                    if let Some(source) = &mut self.source {
295	                        source.wire = Some(target);
296	                    }
297	                    self.push_tool_uses(blocks);
298	                } else if !blocks.is_empty() {
299	                    self.flush_pending_assistant()?;
300	                    self.flush_pending_user()?;
301	                    self.last_item_dropped = false;
302	                    let msg = self.messages.len();
303	                    self.push_message("assistant", blocks)?;
304	                    if let Some(source) = &mut self.source {
305	                        source.wire = Some(msg);
306	                    }
307	                    if let Some(saved) = saved {
308	                        // `push_message` cleared any older tentative message.
309	                        debug_assert!(self.tentative.is_none());
310	                        let group = self
311	                            .source
312	                            .as_ref()
313	                            .map(|s| s.group)
314	                            .expect("a thinking block comes from a valid part");
315	                        self.tentative = Some(Tentative { msg, group, saved });
316	                    }
317	                }
318	            }
319	            Item::ToolCall {
320	                call_id,
321	                name,
322	                args,
323	            } => {
324	                self.last_item_dropped = false;
325	                // A new tool_use follows any results already seen. Close
326	                // that user turn first only when the last assistant round is
327	                // fully answered; otherwise the call joins that round.
328	                if round_is_answered(&self.messages, &self.pending_tool_results) {
329	                    self.flush_pending_user()?;
330	                }
331	                // The call keeps its key only in the wire message that holds
332	                // the blocks of its source message.
333	                let target = self.tool_use_target();
334	                let slot = self.source.as_mut().and_then(|source| {
335	                    let key = source.tool_key(call_id);
336	                    (source.wire == Some(target)).then_some(Slot {
337	                        group: source.group,
338	                        key,
339	                    })
340	                });
341	                let value = json!({
342	                    "type": "tool_use",
343	                    "id": call_id,
344	                    "name": name,
345	                    "input": args,
346	                });
347	                self.push_tool_uses(vec![WireBlock { value, slot }]);
348	            }
349	            Item::ToolResult { call_id, content } => {
350	                self.last_item_dropped = false;
351	                self.flush_pending_assistant()?;
352	                self.pending_tool_results.push(json!({
353	                    "type": "tool_result",
354	                    "tool_use_id": call_id,
355	                    "content": text_of(content),
356	                }));
357	            }
358	            _ => {
359	                tracing::warn!(
360	                    target: "paigasus::anthropic::translate",
361	                    "unknown Item variant; skipping",
362	                );
363	            }
364	        }
365	        Ok(())
366	    }
367	
368	    fn finish(&mut self) -> Result<(), Rollback> {
369	        self.flush_pending_assistant()?;
370	        self.flush_pending_user()?;
371	        match &self.tentative {
372	            Some(t) if !self.messages[t.msg].has_own_block(t.group) => Err(Rollback),
373	            _ => Ok(()),
374	        }
375	    }
376	
377	    /// Push a message. A tentative message before it is then complete: keep
378	    /// it when it has a `text` or `tool_use` block of its own group, else go
379	    /// back.
380	    fn push_message(
381	        &mut self,
382	        role: &'static str,
383	        content: Vec<WireBlock>,
384	    ) -> Result<(), Rollback> {
385	        if let Some(t) = &self.tentative {
386	            debug_assert_eq!(
387	                t.msg + 1,
388	                self.messages.len(),
389	                "a tentative message is last"
390	            );
391	            if !self.messages[t.msg].has_own_block(t.group) {
392	                return Err(Rollback);
393	            }
394	            self.tentative = None;
395	        }
396	        self.messages.push(WireMessage { role, content });
397	        Ok(())
398	    }
399	
400	    fn flush_pending_assistant(&mut self) -> Result<(), Rollback> {
401	        if self.pending_tool_use.is_empty() {
402	            return Ok(());
403	        }
404	        let content = std::mem::take(&mut self.pending_tool_use);
405	        self.push_message("assistant", content)
406	    }
407	
408	    fn flush_pending_user(&mut self) -> Result<(), Rollback> {
409	        if self.pending_tool_results.is_empty() {
410	            return Ok(());
411	        }
412	        let content = std::mem::take(&mut self.pending_tool_results)
413	            .into_iter()
414	            .map(WireBlock::plain)
415	            .collect();
416	        self.push_message("user", content)
417	    }
418	
419	    /// The index of the wire message that `push_tool_uses` adds to now.
420	    fn tool_use_target(&self) -> usize {
421	        match self.messages.last() {
422	            Some(m) if m.role == "assistant" => self.messages.len() - 1,
423	            // Queued blocks flush into the next message.
424	            _ => self.messages.len(),
425	        }
426	    }
427	
428	    /// Add `tool_use` blocks to the open assistant turn. When the last
429	    /// message is an assistant message, extend it. Otherwise queue them.
430	    fn push_tool_uses(&mut self, blocks: Vec<WireBlock>) {
431	        match self.messages.last_mut() {
432	            Some(last) if last.role == "assistant" => last.content.extend(blocks),
433	            _ => self.pending_tool_use.extend(blocks),
434	        }
435	    }
436	
437	    fn save(&self, item: usize) -> Saved {
438	        Saved {
439	            item,
440	            messages_len: self.messages.len(),
441	            system_len: self.system_text.len(),
442	            pending_tool_use: self.pending_tool_use.clone(),
443	            pending_tool_results: self.pending_tool_results.clone(),
444	            last_item_dropped: self.last_item_dropped,
445	            next_group: self.next_group,
446	            source: self.source.clone(),
447	        }
448	    }
449	
450	    /// Go back to `saved`. The messages before `saved.messages_len` did not
451	    /// change after the save: only the last message gets new blocks, and the
452	    /// tentative message and all later ones are at or after that length.
453	    ///
454	    /// `saved` does not hold a tentative message, and the state after the
455	    /// restore has none. This is correct: a tentative message that was active
456	    /// when `saved` was taken was kept by the push of the new tentative
457	    /// message (else that push rolled back to the older save, and this
458	    /// `saved` was discarded). A kept message has a `text` or `tool_use`
459	    /// block of its own group. It is before `saved.messages_len`, so the
460	    /// restore does not change it, and it stays kept.
461	    fn restore(&mut self, saved: Saved) {
462	        self.messages.truncate(saved.messages_len);
463	        self.system_text.truncate(saved.system_len);
464	        self.pending_tool_use = saved.pending_tool_use;
465	        self.pending_tool_results = saved.pending_tool_results;
466	        self.last_item_dropped = saved.last_item_dropped;
467	        self.next_group = saved.next_group;
468	        self.source = saved.source;
469	        self.tentative = None;
470	    }
471	
472	    fn into_output(self) -> TranslatedMessages {
473	        let trailing_message_dropped =
474	            self.last_item_dropped && self.messages.last().is_some_and(|m| m.role == "assistant");
475	        let system = if self.system_text.trim().is_empty() {
476	            None
477	        } else {
478	            Some(Value::String(self.system_text))
479	        };
480	        let messages = self
481	            .messages
482	            .into_iter()
483	            .map(WireMessage::into_value)
484	            .collect();
485	        TranslatedMessages {
486	            system,
487	            messages: Value::Array(messages),
488	            trailing_message_dropped,
489	        }
490	    }
491	}
492	
493	/// Remove each thinking block whose group has no `text` or `tool_use` block
494	/// in this message.
495	fn drop_thinking_without_own_block(content: &mut Vec<WireBlock>) {
496	    let own: Vec<usize> = content
497	        .iter()
498	        .filter(|b| !b.is_thinking())
499	        .filter_map(|b| b.slot.map(|s| s.group))
500	        .collect();
501	    content.retain(|b| !b.is_thinking() || b.slot.is_some_and(|s| own.contains(&s.group)));
502	}
503	
504	/// Put the blocks of each group back in response order.
505	///
506	/// For each group, take the positions its blocks have in the message, sort
507	/// those blocks by key (stable), and write them back into the same
508	/// positions. Blocks of other groups and blocks with no slot do not move.
509	fn sort_groups(content: &mut [WireBlock]) {
510	    let mut groups: Vec<usize> = Vec::new();
511	    for slot in content.iter().filter_map(|b| b.slot) {
512	        if !groups.contains(&slot.group) {
513	            groups.push(slot.group);
514	        }
515	    }
516	    for group in groups {
517	        let at: Vec<usize> = content
518	            .iter()
519	            .enumerate()
520	            .filter(|(_, b)| b.slot.is_some_and(|s| s.group == group))
521	            .map(|(i, _)| i)
522	            .collect();
523	        let first_tool_use = at
524	            .iter()
525	            .filter(|&&i| content[i].is_tool_use())
526	            .filter_map(|&i| match content[i].slot.map(|s| s.key) {
527	                Some(SortKey::At(index, _)) if index != u64::MAX => Some(index),
528	                _ => None,
529	            })
530	            .min()
531	            .unwrap_or(u64::MAX);
532	        let mut taken: Vec<WireBlock> = at
533	            .iter()
534	            .map(|&i| std::mem::take(&mut content[i]))
535	            .collect();
536	        taken.sort_by_key(|b| b.slot.map(|s| s.key.resolve(first_tool_use)));
537	        for (i, block) in at.into_iter().zip(taken) {
538	            content[i] = block;
539	        }
540	    }
541	}
542	
543	/// `true` when every `tool_use` id in the trailing run of assistant messages
544	/// has a matching `tool_result` in `results`. The API joins adjacent
545	/// assistant messages into one turn, so the whole run is one round. Also
546	/// `true` when there is nothing to compare (no assistant message last), so
547	/// the results then flush as before.
548	fn round_is_answered(messages: &[WireMessage], results: &[Value]) -> bool {
549	    messages
550	        .iter()
551	        .rev()
552	        .take_while(|m| m.role == "assistant")
553	        .flat_map(|m| &m.content)
554	        .filter(|b| b.is_tool_use())
555	        .all(|b| results.iter().any(|r| r["tool_use_id"] == b.value["id"]))
556	}
557	
558	/// The API rejects empty and whitespace-only text blocks.
559	fn is_blank(text: &str) -> bool {
560	    text.trim().is_empty()
561	}
562	
563	fn text_of(parts: &[ContentPart]) -> String {
564	    let mut s = String::new();
565	    for p in parts {
566	        if let ContentPart::Text { text } = p {
567	            if !s.is_empty() {
568	                s.push('\n');
569	            }
570	            s.push_str(text);
571	        }
572	    }
573	    s
574	}
575	
576	fn user_blocks(content: &[ContentPart]) -> Vec<Value> {
577	    use paigasus_helikon_core::MediaSource;
578	    content
579	        .iter()
580	        .filter_map(|p| match p {
581	            ContentPart::Text { text } if is_blank(text) => None,
582	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
583	            ContentPart::ToolResult { call_id, content } => Some(json!({
584	                "type": "tool_result",
585	                "tool_use_id": call_id,
586	                "content": text_of(content),
587	            })),
588	            ContentPart::Image { source } => match source {
589	                MediaSource::Url { url } => Some(json!({
590	                    "type": "image",
591	                    "source": {"type": "url", "url": url},
592	                })),
593	                MediaSource::Base64 { mime_type, data } => Some(json!({
594	                    "type": "image",
595	                    "source": {
596	                        "type": "base64",
597	                        "media_type": mime_type,
598	                        "data": data,
599	                    },
600	                })),
601	                _ => {
602	                    tracing::warn!(
603	                        target: "paigasus::anthropic::translate",
604	                        "unsupported MediaSource variant; skipping image",
605	                    );
606	                    None
607	                }
608	            },
609	            // Provider data from another provider has no Anthropic form.
610	            ContentPart::ProviderData { .. } => None,
611	            _ => None,
612	        })
613	        .collect()
614	}
615	
616	/// The blocks of one `AssistantMessage`, and its source state.
617	///
618	/// The source state is `Some` only when at least one part of this crate is
619	/// valid. Then each block gets a slot in group `group`. Else no block gets a
620	/// slot, and the message builds as before SMA-840.
621	fn assistant_blocks(content: &[ContentPart], group: usize) -> (Vec<WireBlock>, Option<Source>) {
622	    // Read each part once, so that a skipped part logs once.
623	    let data: Vec<Option<(AnthropicData, Option<&str>)>> =
624	        content.iter().map(provider_data::from_part).collect();
625	    let mut source = data.iter().any(Option::is_some).then(|| Source {
626	        group,
627	        wire: None,
628	        tool_positions: HashMap::new(),
629	    });
